package care.achillea;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.http.HttpStatus;
import org.springframework.web.server.ResponseStatusException;
import java.time.Instant;
import java.util.*;
import static care.achillea.Model.*;
@Service
public class CareService {
 private final StoreRepository repo; private final ObjectMapper json; private final SensorAdapter sensor=new SensorAdapter.Simulator();
 public CareService(StoreRepository repo,ObjectMapper json){this.repo=repo;this.json=json;}
 private String id(){return UUID.randomUUID().toString();}
 static void require(boolean condition,String message){if(!condition)throw new ResponseStatusException(HttpStatus.CONFLICT,message);}
 public State read(){try{return repo.findById("demo").map(s->{try{return json.readValue(s.payload,State.class);}catch(Exception e){throw new IllegalStateException(e);}}).orElseGet(this::reset);}catch(Exception e){throw e;}}
 private State save(State s){try{Store row=repo.findById("demo").orElse(new Store("demo",""));row.payload=json.writeValueAsString(s);repo.saveAndFlush(row);return s;}catch(Exception e){throw new IllegalStateException(e);}}
 void event(State s,String patient,String type,String source,String details){s.events.add(new Event(id(),patient,type,source,details,Instant.now()));}
 @Transactional public synchronized State reset(){State s=new State();Instant now=Instant.now();
 s.patients.addAll(List.of(new Patient("synthetic-ld-01","Maya Rowan","201","L_AND_D","Bedside observations and comfort review","nurse-demo",false),new Patient("synthetic-ld-02","Elena Vale","204","L_AND_D","Scheduled assessment and documentation","nurse-demo",false),new Patient("synthetic-icu-01","Alex Linden","108","ICU","Postoperative care · prescribed positioning review","nurse-demo",true)));
 s.tasks.addAll(List.of(new Task("task-1","synthetic-ld-01","Review bedside observations","ASSESSMENT",now.minusSeconds(300),false,1),new Task("task-2","synthetic-ld-02","Comfort and care-plan review","ASSESSMENT",now.plusSeconds(900),false,2),new Task("task-3","synthetic-icu-01","Review prescribed repositioning","REPOSITION_REVIEW",now.minusSeconds(600),true,3),new Task("task-4","synthetic-ld-01","Document bedside assessment","DOCUMENTATION",now.plusSeconds(2400),false,4)));
 for(Patient p:s.patients){for(int i=0;i<5;i++){Instant at=now.minusSeconds((5-i)*60L);s.vitals.add(new Vital(id(),p.id(),"HEART_RATE",76+i,"bpm",at,at,"SIMULATED_MONITOR","seed-"+p.id()+i,"VALID"));}s.vitals.add(new Vital(id(),p.id(),"SPO2",98,"%",now,now,"SIMULATED_MONITOR","seed-spo2-"+p.id(),"VALID"));}
 event(s,null,"demo.reset","SIMULATOR","Synthetic baseline restored");return save(s);}
 public Patient patient(State s,String id){return s.patients.stream().filter(p->p.id().equals(id)&&p.nurseId().equals("nurse-demo")).findFirst().orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Assigned patient not found"));}
 @Transactional public synchronized Vital ingest(Observation input){
  if(input.sourceEventId()==null||input.sourceEventId().isBlank()||input.sourceEventId().length()>160||input.observedAt()==null||input.observedAt().isAfter(Instant.now().plusSeconds(60))||!Double.isFinite(input.value()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Valid source event ID, value, and observation timestamp required");
  String expected=switch(Objects.toString(input.metric(),"")){case "HEART_RATE"->"bpm";case "SPO2"->"%";case "TEMPERATURE"->"°C";case "RESPIRATORY_RATE"->"breaths/min";default->throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Unsupported metric");};
  if(!expected.equals(input.unit())||!List.of("VALID","SUSPECTED_ARTIFACT","MISSING","UNKNOWN").contains(Objects.toString(input.quality(),"")))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Metric unit or quality invalid");
  State s=read();patient(s,input.patientId());Optional<Vital> previous=s.vitals.stream().filter(v->v.sourceEventId().equals(input.sourceEventId())).findFirst();if(previous.isPresent()){Vital v=previous.get();require(v.patientId().equals(input.patientId())&&v.metric().equals(input.metric())&&v.value()==input.value(),"Source event ID was already used for different data");return v;}
  Vital v=new Vital(id(),input.patientId(),input.metric(),input.value(),input.unit(),input.observedAt(),Instant.now(),"SIMULATED_MONITOR",input.sourceEventId(),input.quality());s.vitals.add(v);event(s,v.patientId(),"vital.received","SIMULATED_MONITOR","Observation ingested with source event ID "+input.sourceEventId());save(s);return v;
 }
 Task task(State s,String id){return s.tasks.stream().filter(t->t.id.equals(id)).findFirst().orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Task not found"));}
 Chart chart(State s,String id){return s.charts.stream().filter(c->c.id.equals(id)).findFirst().orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Chart not found"));}
 public List<Round> rounds(State s,String unit){Instant now=Instant.now();return s.tasks.stream().filter(t->!List.of("COMPLETED","CANCELLED").contains(t.status)&&patient(s,t.patientId).unit().equals(unit)).map(t->{int rank=t.priority.equals("HIGH")?0:t.dueAt.isBefore(now)?1:t.dueAt.isBefore(now.plusSeconds(1800))?2:3;return new Round(t,rank==0?"Explicit high priority (demo rule)":rank==1?"Past scheduled due time":rank==2?"Due within 30 minutes":"Routine · nurse-selected sequence",rank);}).sorted(Comparator.comparingInt(Round::rank).thenComparingInt(r->r.rank()==3?r.task().order:0).thenComparing(r->r.task().dueAt).thenComparing(r->r.task().id)).toList();}
 @Transactional public synchronized Chart draft(Draft d,String existing,String amendment){State s=read();patient(s,d.patientId());require(d.text()!=null&&!d.text().isBlank(),"Enter an observation before saving");require(d.text().length()<=5000,"Note too long");Chart c=existing==null?new Chart():chart(s,existing);require(c.status.equals("DRAFT"),"Confirmed entries are immutable; append an amendment");if(existing!=null)require(c.patientId.equals(d.patientId()),"Patient cannot change");
 if(d.linkedTaskId()!=null)require(task(s,d.linkedTaskId()).patientId.equals(d.patientId()),"Task belongs to another patient");
 List<String> links=d.linkedVitalIds()==null?List.of():d.linkedVitalIds();for(String v:links)require(s.vitals.stream().anyMatch(x->x.id().equals(v)&&x.patientId().equals(d.patientId())),"Invalid linked observation");
 if(amendment!=null){Chart original=chart(s,amendment);require(!original.status.equals("DRAFT")&&original.patientId.equals(d.patientId()),"Only confirmed entries can be amended");}
 c.patientId=d.patientId();c.type=d.type()==null?"OBSERVATION":d.type();c.text=d.text();c.linkedTaskId=d.linkedTaskId();c.linkedVitalIds=new ArrayList<>(links);c.linkedMovementId=d.linkedMovementId();c.amendmentOfId=amendment;c.provenance=links.isEmpty()?"MANUAL_ENTRY":"MANUAL_ENTRY + SIMULATED_MONITOR (linked immutable observations)";
 if(existing==null){c.id=id();c.authoredAt=Instant.now();s.charts.add(c);}event(s,c.patientId,"chart.draft","nurse-demo","Draft saved");save(s);return c;}
 @Transactional public synchronized State confirm(String id,Command cmd){State s=read();Chart c=chart(s,id);patient(s,c.patientId);require(c.status.equals("DRAFT"),"Entry already confirmed");require(Boolean.TRUE.equals(cmd.verified()),"Review and verify the entry first");c.status=c.amendmentOfId==null?"CONFIRMED":"AMENDED";c.confirmedAt=Instant.now();event(s,c.patientId,"chart.confirmed","nurse-demo","Entry confirmed with provenance: "+c.provenance);return save(s);}
 @Transactional public synchronized State taskCommand(String id,String action,Command c){State s=read();Task t=task(s,id);patient(s,t.patientId);require(!t.status.equals("COMPLETED"),"Completed task cannot change");switch(action){case "acknowledge"->t.status="ACKNOWLEDGED";case "defer"->{require(c.reason()!=null&&!c.reason().isBlank(),"Deferral reason is required");t.status="DEFERRED";t.deferReason=c.reason();t.dueAt=Instant.now().plusSeconds(1800);}case "reorder"->{require(t.priority.equals("ROUTINE")&&t.dueAt.isAfter(Instant.now().plusSeconds(1800)),"Only routine future tasks may move");require(c.order()!=null,"Order is required");t.order=c.order();}case "priority"->{require(List.of("ROUTINE","TIMELY","HIGH").contains(c.priority()),"Invalid priority");t.priority=c.priority();}case "complete"->{require(Boolean.TRUE.equals(c.verified()),"Nurse verification is required");if(t.verificationRequired){require(c.movementId()!=null,"Review and confirm a movement first");Movement m=movement(s,c.movementId());require(m.patientId.equals(t.patientId)&&m.verificationStatus.equals("CONFIRMED_CARE"),"Movement must be nurse-confirmed care for this patient");}t.status="COMPLETED";t.completedAt=Instant.now().toString();t.verifiedBy="nurse-demo";Chart note=new Chart();note.id=id();note.patientId=t.patientId;note.type="TASK_COMPLETION";note.text=c.text()==null?t.title+" — verified by demo nurse":c.text();note.status="CONFIRMED";note.authoredAt=note.confirmedAt=Instant.now();note.linkedTaskId=t.id;note.linkedMovementId=c.movementId();note.provenance="NURSE_VERIFIED_CARE";s.charts.add(note);}default->throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Unknown task action");}event(s,t.patientId,"task."+action,"nurse-demo",t.title+(c.reason()==null?"":" · "+c.reason()));return save(s);}
 Movement movement(State s,String id){return s.movements.stream().filter(m->m.id.equals(id)).findFirst().orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Movement not found"));}
 @Transactional public synchronized State review(String id,Command c){State s=read();Movement m=movement(s,id);patient(s,m.patientId);require(List.of("CONFIRMED_CARE","NOT_CARE","NEEDS_REVIEW").contains(c.status()),"Invalid review status");require(!m.verificationStatus.equals("CONFIRMED_CARE"),"Care already confirmed");if(c.status().equals("CONFIRMED_CARE"))require(Boolean.TRUE.equals(c.verified())&&c.text()!=null&&!c.text().isBlank(),"Verification and bedside observation required");m.verificationStatus=c.status();m.reviewerId="nurse-demo";m.reviewedAt=Instant.now().toString();event(s,m.patientId,"movement.reviewed","nurse-demo",c.status()+" · "+Objects.toString(c.text(),""));return save(s);}
 @Transactional public synchronized State scenario(String key,String patientId){State s=read();if(List.of("vital","flagged").contains(key)){String pid=patientId==null?"synthetic-ld-01":patientId;patient(s,pid);Instant now=Instant.now();long count=s.vitals.stream().filter(v->v.patientId().equals(pid)).count();s.vitals.add(new Vital(id(),pid,"HEART_RATE",key.equals("flagged")?124:78+count%7,"bpm",now,now,"SIMULATED_MONITOR",id(),key.equals("flagged")?"REVIEW_REQUESTED_DEMO_RULE":"VALID"));event(s,pid,"vital.received","SIMULATED_MONITOR","New synthetic heart-rate observation");if(key.equals("flagged")&&s.tasks.stream().noneMatch(t->t.patientId.equals(pid)&&t.type.equals("VITAL_REVIEW")&&!t.status.equals("COMPLETED"))){Task t=new Task(id(),pid,"Review latest synthetic reading","VITAL_REVIEW",now,false,0);t.priority="HIGH";t.source="SIMULATED_MONITOR_DEMO_RULE";s.tasks.add(t);}}
 else {require(List.of("partial","coordinated","disconnect","reconnect","no-movement").contains(key),"Unknown scenario");Movement prev=s.movements.isEmpty()?null:s.movements.getLast();Movement m=sensor.sample(key,prev);if(prev!=null&&prev.quality.equals("PELVIS_DISCONNECTED")&&!key.equals("reconnect")){m.quality="PELVIS_DISCONNECTED";m.classification="UNKNOWN";m.sampleIds=List.of(m.id+"-chest");m.pelvisAfter=m.pelvisBefore;}s.movements.add(m);s.samples.add(new OrientationSample(m.id+"-chest","torso-sim-01",m.patientId,"UPPER_TORSO",m.chestAfter,m.capturedAt,Instant.now(),"SIMULATED_GOOD","SIMULATED"));if(!m.quality.equals("PELVIS_DISCONNECTED"))s.samples.add(new OrientationSample(m.id+"-pelvis","pelvis-sim-01",m.patientId,"PELVIS",m.pelvisAfter,m.capturedAt,Instant.now(),"SIMULATED_GOOD","SIMULATED"));event(s,m.patientId,"movement.candidate","SIMULATED_SENSOR",m.classification+" · "+m.quality+" · prototype heuristic");if(key.equals("no-movement"))s.tasks.stream().filter(t->t.type.equals("REPOSITION_REVIEW")&&!t.status.equals("COMPLETED")).forEach(t->t.dueAt=Instant.now().minusSeconds(1));}
 event(s,null,"demo.trigger","SIMULATOR",key);return save(s);}
}
